INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('cishan','磁山文化','culture','span',NULL,'approximate_year','approximate_year','约前6000—前5600年；碳十四测年和校正年代的表述因测年批次及采用框架而异。',NULL,NULL,NULL,NULL,-6000,1,NULL,-71988,-5600,12,NULL,-67177,'河北南部太行山东麓的新石器文化，以磁山遗址命名。陶盂与支架、石磨盘和磨棒、窖穴及植物遗存，为研究北方早期定居聚落和农业生计提供了重要材料。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('dawenkou','大汶口文化','culture','span',NULL,'approximate_year','approximate_year','约前4300–前2500；一说稍早自前4500，约前2500过渡为龙山。',NULL,NULL,NULL,NULL,-4300,1,NULL,-51588,-2500,12,NULL,-29977,'以山东泰安大汶口命名，海岱地区新石器文化。陶鬶、拔牙习俗与陶器刻画符号，下接山东龙山文化。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('erlitou','二里头文化','culture','span',NULL,'approximate_year','approximate_year','2015年AMS：文化早不过前1900、晚不过前1500；一期约前1750，四期约止于前1520。亦作约前1800–前1500。与文献夏朝不能简单等同。',NULL,NULL,NULL,NULL,-1750,1,NULL,-20988,-1520,12,NULL,-18217,'河南偃师二里头，中原最早的大型都邑之一。宫城、青铜礼器与绿松石龙，是探索夏商分界与早期国家的核心遗存。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hemudu','河姆渡文化','culture','span',NULL,'approximate_year','approximate_year','河姆渡遗址四期碳十四：一期约前5000–前4500，四期约前3600–前3300；亦作前5000–前3000。',NULL,NULL,NULL,NULL,-5000,1,NULL,-59988,-3300,12,NULL,-39577,'浙江余姚河姆渡，长江下游新石器文化。干栏式建筑、夹炭黑陶与大量栽培稻谷，证明江南史前稻作与定居。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('hongshan','红山文化','culture','span',NULL,'approximate_year','approximate_year','约前4700–前2900，与仰韶中晚期相当。',NULL,NULL,NULL,NULL,-4700,1,NULL,-56388,-2900,12,NULL,-34777,'西辽河流域新石器文化，内蒙古赤峰红山及辽宁牛河梁为代表。玉龙、积石冢与女神庙，显示早期礼仪中心。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jiahu','贾湖文化','culture','span',NULL,'approximate_year','approximate_year','贾湖遗址三期约距今9000–7800年；骨笛分期作前7000–前5800。一说属裴李岗文化类型。',NULL,NULL,NULL,NULL,-7000,1,NULL,-83988,-5800,12,NULL,-69577,'河南舞阳贾湖，新石器早期聚落。出土七声音阶骨笛、炭化稻、龟甲契刻符号，为黄河—淮河间早期文化的代表。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('laoguantai-dadiwan-i','老官台／大地湾一期文化','culture','span',NULL,'approximate_year','approximate_year','约前6000—前5000年；老官台、大地湾一期、白家村等名称及涵盖范围在学界存在分歧，年代为前仰韶阶段的概括范围。',NULL,NULL,NULL,NULL,-6000,1,NULL,-71988,-5000,12,NULL,-59977,'渭河流域的前仰韶时期遗存，以秦安大地湾一期、临潼老官台等遗址为代表。陶器、石器、房址和农业相关遗存，呈现西北地区由采集狩猎向定居与早期农业发展的过程。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('liangzhu','良渚文化','culture','span',NULL,'approximate_year','approximate_year','通行约前3300–前2300；亦记距今约5300–4000年（约前3300–前2000）。',NULL,NULL,NULL,NULL,-3300,1,NULL,-39588,-2300,12,NULL,-27577,'环太湖地区新石器晚期文化。良渚古城、水利系统与琮璧钺玉礼器，常被视为长江下游早期国家形态。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('longshan','龙山文化','culture','span',NULL,'approximate_year','approximate_year','距今约5000–4000年；山东龙山约前2500–前2000。此取黄河中下游龙山时代总范围。',NULL,NULL,NULL,NULL,-3000,1,NULL,-35988,-2000,12,NULL,-23977,'新石器晚期黑陶文化，分布于山东、河南、山西、陕西等地。蛋壳黑陶、夯土城址，下接二里头等早期青铜文化。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('majiayao','马家窑文化','culture','span',NULL,'approximate_year','approximate_year','约前3300–前2100。马家窑、半山、马厂为同一文化诸类型。',NULL,NULL,NULL,NULL,-3300,1,NULL,-39588,-2100,12,NULL,-25177,'甘青地区新石器文化，仰韶西向发展的一支。以精美彩陶著称，林家等地出土早期青铜小刀。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('peiligang','裴李岗文化','culture','span',NULL,'approximate_year','approximate_year','约前7000—前5000年；区域遗址年代与分期略有差异。贾湖遗存二、三期与裴李岗文化大体同时，一期较早；学界对贾湖遗存是否单列为文化或归入裴李岗文化有不同处理。',NULL,NULL,NULL,NULL,-7000,1,NULL,-83988,-5000,12,NULL,-59977,'河南中西部至淮河上游的新石器文化，聚落、墓地、陶器及磨盘磨棒等遗存显示定居生活和农业发展。贾湖遗存与其有密切的年代和文化联系，但分类关系仍有不同说法。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('sanxingdui','三星堆文化','culture','span',NULL,'approximate_year','approximate_year','遗址约前2800–前1100。一期属宝墩文化；二三期三星堆文化约前2000–前1400；著名祭祀坑约前1200–前1000，属四期十二桥。不含宝墩一期。',NULL,NULL,NULL,NULL,-2000,1,NULL,-23988,-1100,12,NULL,-13177,'四川广汉三星堆，古蜀青铜文明。纵目面具、神树、金杖与大型祭祀坑，与中原夏商并行而风格迥异。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('shimao','石峁','culture','span',NULL,'approximate_year','approximate_year','石峁城址属龙山晚期，通行碳十四约前2300–前1800（距今约4300–3800年）。',NULL,NULL,NULL,NULL,-2300,1,NULL,-27588,-1800,12,NULL,-21577,'陕西神木石峁，目前所见中国史前规模最大的石构城址。皇城台、玉器与石雕，为河套—陕北早期邦国遗存。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('taosi','陶寺文化','culture','span',NULL,'approximate_year','approximate_year','陶寺中期约前2100–前2000；观象台或可上溯至距今约4700年。此取龙山时代晋南陶寺通行年。',NULL,NULL,NULL,NULL,-2300,1,NULL,-27588,-1900,12,NULL,-22777,'山西襄汾陶寺，晋南龙山时代都邑。宫殿、观象台、朱书扁壶与等级墓葬，常被用以探索早期国家与尧都传说。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('yangshao','仰韶文化','culture','span',NULL,'approximate_year','approximate_year','约前5000–前2700。半坡、庙底沟等为地方类型。',NULL,NULL,NULL,NULL,-5000,1,NULL,-59988,-2700,12,NULL,-32377,'以河南渑池仰韶村命名，分布于黄河中游。彩陶、农业村落与半地穴房屋，是中原新石器中期的主干文化。',NULL,NULL,'[]');
